        public static readonly Color Chrome=CyberTheme.Background,Sidebar=CyberTheme.Surface,Inspector=CyberTheme.Surface,Lane=CyberTheme.Background,Text=CyberTheme.Text,Blue=Color.FromArgb(24,82,153);
        public static GraphicsPath Rounded(RectangleF r,float radius){GraphicsPath p=new GraphicsPath();p.AddRectangle(r);return p;}
        public static void Box(Graphics g,Rectangle r,Color top,Color bottom,int radius){if(r.Width<1||r.Height<1)return;using(SolidBrush b=new SolidBrush(top))using(Pen line=new Pen(CyberTheme.Border)){g.FillRectangle(b,r);g.DrawRectangle(line,r.X,r.Y,Math.Max(0,r.Width-1),Math.Max(0,r.Height-1));}}
        public static void Label(Graphics g,string text,Font font,Rectangle r,Color color,TextFormatFlags flags){if(r.Width<=0||r.Height<=0)return;using(var f=new Font(font.FontFamily,font.SizeInPoints*96/72,font.Style,GraphicsUnit.Pixel))using(var brush=new SolidBrush(color))using(var format=(flags&TextFormatFlags.NoPadding)!=0?(StringFormat)StringFormat.GenericTypographic.Clone():new StringFormat{Trimming=StringTrimming.EllipsisCharacter,FormatFlags=StringFormatFlags.NoWrap}){format.Alignment=(flags&TextFormatFlags.HorizontalCenter)!=0?StringAlignment.Center:(flags&TextFormatFlags.Right)!=0?StringAlignment.Far:StringAlignment.Near;format.LineAlignment=(flags&TextFormatFlags.VerticalCenter)!=0?StringAlignment.Center:StringAlignment.Near;g.DrawString(UiText.Translate(text??String.Empty),f,brush,r,format);}}
        public static void Icon(Graphics g,string id,Rectangle r,Color color){float x=r.X+r.Width/2f,y=r.Y+r.Height/2f;using(Pen p=new Pen(color,1.55f)){p.StartCap=p.EndCap=LineCap.Round;using(SolidBrush b=new SolidBrush(color)){
            if(id=="play")g.FillPolygon(b,new[]{new PointF(x-4,y-6),new PointF(x+6,y),new PointF(x-4,y+6)});
            else if(id=="stop")g.FillRectangle(b,x-4.5f,y-4.5f,9,9);
            else if(id=="pause"){g.FillRectangle(b,x-4,y-5,3,10);g.FillRectangle(b,x+2,y-5,3,10);}
            else if(id=="record")g.FillEllipse(b,x-5,y-5,10,10);
            else if(id=="back"||id=="forward"){float d=id=="back"?-1:1;g.FillPolygon(b,new[]{new PointF(x+d*6,y),new PointF(x-d*1,y-5),new PointF(x-d*1,y+5)});g.FillPolygon(b,new[]{new PointF(x-d*1,y),new PointF(x-d*8,y-5),new PointF(x-d*8,y+5)});}
            else if(id=="start"){g.DrawLine(p,x-5,y-5,x-5,y+5);g.FillPolygon(b,new[]{new PointF(x-3,y),new PointF(x+5,y-5),new PointF(x+5,y+5)});}
            else if(id=="cycle"){g.DrawArc(p,x-7,y-5,14,10,20,260);g.DrawLine(p,x+6,y-5,x+6,y);g.DrawLine(p,x+6,y-5,x+1,y-5);}
            else if(id=="library"){g.DrawRectangle(p,x-7,y-6,14,12);g.DrawLine(p,x-7,y-2,x+7,y-2);g.DrawLine(p,x-7,y+2,x+7,y+2);g.DrawLine(p,x-2,y-6,x-2,y+6);}
            else if(id=="inspector"){g.DrawEllipse(p,x-7,y-7,14,14);g.DrawLine(p,x,y-1,x,y+4);g.FillEllipse(b,x-1,y-5,2,2);}
            else if(id=="mixer"){for(int i=-1;i<=1;i++){float xx=x+i*5;g.DrawLine(p,xx,y-7,xx,y+7);g.FillRectangle(b,xx-2,y+(i==0?2:-4),4,3);}}
            else if(id=="editor"){g.DrawLine(p,x-6,y+6,x+5,y-5);g.DrawLine(p,x-4,y+7,x+7,y-4);g.DrawLine(p,x-6,y+6,x-4,y+7);g.DrawLine(p,x+5,y-5,x+7,y-4);}
            else if(id=="keyboard"){g.DrawRectangle(p,x-9,y-6,18,12);for(int i=-2;i<=2;i++)g.DrawLine(p,x+i*3,y,x+i*3,y+6);for(int i=-2;i<=2;i++)if(i!=0)g.FillRectangle(b,x+i*3-1,y-6,2,7);}
            else if(id=="gear"){g.DrawEllipse(p,x-5,y-5,10,10);g.DrawEllipse(p,x-1.5f,y-1.5f,3,3);for(int i=0;i<8;i++){double a=i*Math.PI/4;g.DrawLine(p,x+(float)Math.Cos(a)*6,y+(float)Math.Sin(a)*6,x+(float)Math.Cos(a)*8,y+(float)Math.Sin(a)*8);}}
            else if(id=="plus"){g.DrawLine(p,x-5,y,x+5,y);g.DrawLine(p,x,y-5,x,y+5);}
            else if(id=="audio"){for(int i=-5;i<=5;i++){float h=2+(float)Math.Abs(Math.Sin(i*2))*5;g.DrawLine(p,x+i*1.8f,y-h,x+i*1.8f,y+h);}}
            else if(id=="duplicate"){g.DrawRectangle(p,x-6,y-3,10,9);g.DrawLines(p,new[]{new PointF(x-3,y-6),new PointF(x+7,y-6),new PointF(x+7,y+3)});}
            else if(id=="pointer")g.DrawPolygon(p,new[]{new PointF(x-3,y-7),new PointF(x-3,y+6),new PointF(x,y+2),new PointF(x+3,y+7),new PointF(x+5,y+6),new PointF(x+2,y+1),new PointF(x+7,y+1)});
        }}}
        public static PluginSlot InstrumentPlugin(Track track){foreach(PluginSlot slot in track.Plugins)if(slot.IsInstrument)return slot;return null;}
        public static string InstrumentName(Track track){PluginSlot slot=InstrumentPlugin(track);return slot==null?(track.ExternalMidi?"External MIDI":"Sampler"):slot.Name+(slot.Bypassed?" · Bypassed":String.Empty);}
        public static Color TrackColor(Track track,int index,StudioState studio=null){Color[] colors={Color.FromArgb(218,35,82),Color.FromArgb(0,158,210),Color.FromArgb(104,77,214),Color.FromArgb(213,100,24),Color.FromArgb(203,165,17),Color.FromArgb(9,157,82),Color.FromArgb(40,107,210),Color.FromArgb(16,145,147),Color.FromArgb(173,55,173)};Color fallback=colors[Math.Abs(track.ColorIndex==0?index:track.ColorIndex)%colors.Length];return studio==null?fallback:studio.Background(track.Id,false,fallback);}
        public static void KeyboardArtwork(Graphics g,Rectangle r,Color c){float x=r.X+r.Width*.16f,y=r.Y+r.Height*.17f,w=r.Width*.68f,h=r.Height*.34f;using(Pen p=new Pen(c,3)){g.DrawPolygon(p,new[]{new PointF(x,y),new PointF(x+w,y),new PointF(x+w+4,y+h),new PointF(x-4,y+h)});g.DrawLine(p,x-4,y+h+7,x+w+4,y+h+7);g.DrawLine(p,x-4,y+h,x-4,y+h+7);g.DrawLine(p,x+w+4,y+h,x+w+4,y+h+7);g.DrawLine(p,x+3,y+h+7,x+3,r.Bottom-r.Height*.12f);g.DrawLine(p,x+w-3,y+h+7,x+w-3,r.Bottom-r.Height*.12f);for(int i=0;i<3;i++)g.DrawEllipse(p,x+10+i*12,y+8,4,4);}}
    }
    public sealed class StudioMenuRenderer:ToolStripProfessionalRenderer {
      public StudioMenuRenderer(ProfessionalColorTable colors):base(colors){RoundedEdges=false;}
