    }
    public sealed class StudioStripRenderer:ToolStripProfessionalRenderer {
      protected override void OnRenderToolStripBackground(ToolStripRenderEventArgs e){using(var b=new SolidBrush(CyberTheme.Surface))e.Graphics.FillRectangle(b,e.AffectedBounds);}
      protected override void OnRenderToolStripBorder(ToolStripRenderEventArgs e){}
      protected override void OnRenderButtonBackground(ToolStripItemRenderEventArgs e){var button=e.Item as ToolStripButton;bool active=button!=null&&button.Checked;Rectangle r=new Rectangle(0,1,e.Item.Width-1,Math.Max(1,e.Item.Height-2));using(var b=new SolidBrush(active?CyberTheme.AccentDark:e.Item.Selected?CyberTheme.Selection:CyberTheme.Surface))e.Graphics.FillRectangle(b,r);}
      protected override void OnRenderItemText(ToolStripItemTextRenderEventArgs e){e.TextColor=e.Item.Enabled?Color.FromArgb(235,237,241):Color.Gray;base.OnRenderItemText(e);}
    }
