        bool compact=ClientSize.Width<1150;int lcdWidth=compact?400:ClientSize.Width<1400?438:500;int lx=compact?302:(ClientSize.Width-lcdWidth)/2+48;int tx=lx-230;AppCommand[] commands={AppCommand.GoToBeginning,AppCommand.RewindBar,AppCommand.ForwardBar,AppCommand.Stop,AppCommand.PlayOrStop,AppCommand.Pause,AppCommand.Record,AppCommand.ToggleCycle};string[] icons={"start","back","forward","stop","play","pause","record","cycle"};for(int i=0;i<commands.Length;i++){bool active=(commands[i]==AppCommand.PlayOrStop&&_playing)||(commands[i]==AppCommand.Record&&_recording)||(commands[i]==AppCommand.ToggleCycle&&_project!=null&&_project.CycleEnabled);Button(g,commands[i],icons[i],new Rectangle(tx+i*28,16,28,27),active);}
