    public static class ValuePrompt
    {public static double? Ask(IWin32Window owner,string title,double value,double min,double max,int decimals){using(Form f=new Form{Text=title,FormBorderStyle=FormBorderStyle.FixedDialog,StartPosition=FormStartPosition.CenterParent,ClientSize=new Size(255,98),BackColor=Color.FromArgb(65,65,65),ForeColor=Color.WhiteSmoke,MinimizeBox=false,MaximizeBox=false}){NumericUpDown n=new NumericUpDown{Minimum=(decimal)min,Maximum=(decimal)max,DecimalPlaces=decimals,Value=(decimal)Math.Max(min,Math.Min(max,value)),Bounds=new Rectangle(16,16,220,26)};Button ok=new Button{Text="OK",DialogResult=DialogResult.OK,Bounds=new Rectangle(157,56,80,27)};f.Controls.Add(n);f.Controls.Add(ok);f.AcceptButton=ok;return f.ShowDialog(owner)==DialogResult.OK?(double?)n.Value:null;}}}
    public static class MeterPrompt
